def transform(grid):
    h = len(grid)
    out = [[0] * 7 for _ in range(h)]

    marker = next((c for row in grid for c, v in enumerate(row) if v == 5), 8)
    c = max(0, min(6, marker - 8))
    r = 0
    out[r][c] = 5

    objects = []
    # Read all motifs down the left panel, then down the right panel.
    for side in (0, 4):
        for top in range(0, h - 2, 4):
            vals = [grid[rr][cc]
                    for rr in range(top, min(top + 3, h))
                    for cc in range(side, min(side + 3, len(grid[0])))]
            color = next((v for v in vals if v not in (0, 4, 5)), None)
            if color is not None:
                objects.append(color)

    for color in objects:
        if color == 6:
            for _ in range(2):
                r += 1
                if r < h:
                    out[r][c] = color
        else:
            length = {1: 3, 2: 2, 3: 4}.get(color, 1)
            direction = 1 if color == 1 else -1
            r += 1
            for k in range(length):
                cc = c + direction * k
                if r < h and 0 <= cc < 7:
                    out[r][cc] = color
            c += direction * (length - 1)

    return out
